"""One-time migration of the authored manuscript; never touches experiment sources."""
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
S=ROOT/'sections'

def notes(name, entries):
    path=S/f'{name}.html'
    text=path.read_text(encoding='utf-8')
    equations=list(re.finditer(r'<div class="equation">.*?</div>',text,re.S))
    assert len(equations)==len(entries),(name,len(equations),len(entries))
    for match,entry in reversed(list(zip(equations,entries))):
        text=text[:match.end()]+f'\n<div class="math-reading"><b>Symbols and meaning.</b> {entry}</div>'+text[match.end():]
    path.write_text(text,encoding='utf-8')

p=S/'architecture.html';s=p.read_text(encoding='utf-8')
s=s.replace('381,264 learned parameters','381,654 learned parameters in the completed 16-task continuation (381,264 in its 13-task parent)').replace('Thirteen small output layers','Sixteen small output layers')
s=s.replace(r'\(G_t=(R_t+G_t^{\rm channel}+B_t)/3\)',r'\(I_t^{\rm gray}(x,y)=[X_{t,R}(x,y)+X_{t,G}(x,y)+X_{t,B}(x,y)]/3\). Here \(X_{t,R}\), \(X_{t,G}\), and \(X_{t,B}\) are the red, green, and blue pixel channels of the same frame; the capital letters after the comma name channels. The distinct symbol \(I_t^{\rm gray}\) always denotes their grayscale average')
s=s.replace(r'\widehat G',r'\widehat I^{\rm gray}').replace(r'G_{t,p}',r'I^{\rm gray}_{t,p}').replace(r'G_{t-1}',r'I^{\rm gray}_{t-1}').replace(r'G_{x_',r'I^{\rm gray}_{x_')
s=s.replace(r'\(D=|\bar p_O-\bar p_R|\)',r'\(\Delta p=|\bar p_O-\bar p_R|\)').replace(r'10qD',r'10q\Delta p').replace(r'\sum_kD_k',r'\sum_k\Delta p_k')
s=s.replace(r'+b_f+P_i',r'+b_f+e_i^{\rm pos}').replace(r'\(P_i\) is a learned positional',r'\(e_i^{\rm pos}\) is a learned positional')
s=s.replace('For output channel \\(o\\), input channel \\(c\\), stride \\(s\\), and padding \\(p\\), the library\'s operation is \\(Y_{o,i,j}=b_o+\\sum_{c,a,b}K_{o,c,a,b}X_{c,si+a-p,sj+b-p}\\)',r'For output channel \(o\), input channel \(k\), output row and column \(r,c\), kernel row and column \(u,v\), stride \(s\), and padding \(p\), the library operation is \(Y_{o,r,c}=b_o+\sum_{k,u,v}K_{o,k,u,v}X_{k,sr+u-p,sc+v-p}\). Here \(Y\) is the output image of features, \(X\) is the input, \(K\) contains learned kernel weights, and \(b_o\) is the learned bias of output channel \(o\)')
guide=r'''<div class="callout"><strong>How to read the notation</strong><p>A subscript usually indexes time, location, or channel; a superscript such as “gray,” “pos,” or “selected” labels a kind of quantity and is not an exponent. A hat denotes an estimate or prediction, a tilde denotes a transformed value, and a bar denotes a local average or explicitly defined effective quantity. Square brackets with a semicolon concatenate vectors; they do not add them. The symbol \(\odot\) means multiply corresponding entries. The symbol \(*\) denotes convolution, \(\|x\|_2\) is Euclidean vector length, and \(x^\mathsf T y\) is a dot product. Learned matrices are named \(W\), convolution kernels \(K\), and biases \(b\), with labels identifying their layers. The same letter in a different tutorial is defined locally; grayscale never uses the ambiguous letter G.</p><p>For each equation below, the adjacent explanation names its inputs, output, and operation. Numbers such as 64 and 100 are dimensions, while small constants such as \(10^{-8}\) prevent division by zero. Numerical stability constants are not additional sensory signals. A symbol's role must be read from its definition, not guessed from its letter.</p></div>'''
s=s.replace('<h3 id="notation">',guide+'\n<h3 id="notation">')
p.write_text(s,encoding='utf-8')

notes('architecture',[
r'\(A_t\) is the 32-channel appearance field at frame \(t\). \(K_1,K_2\) and \(b_1,b_2\) are the two layers’ learned kernels and biases. The star applies each convolution over the image. GELU transforms each channel value nonlinearly; Pool averages the second layer to 10 × 10 sites. Read from the innermost parentheses outward: center pixels, convolve, transform, convolve, transform, pool.',
r'\(\Omega_i\) is the set of 100 pixels in image block \(i\); \(p\) indexes a pixel and \(k\) an RGB channel. \(\mu_{t,i,k}\) is that block’s mean channel value after subtracting 0.5. \(e_{t,i}\) averages squared grayscale deviation from 0.5; its square root is an intensity-scale feature. \(a^{\rm raw}_{t,i}\) concatenates four numbers. The shortened labels \(\mu_R,\mu_G,\mu_B\) refer to the same time and block. Example: an entirely 0.7-gray block has grayscale RMS 0.2, although its within-block standard deviation is zero.',
r'\(n,x,y\) are integer positions from 0 to 23 within a crop. \(w(n)\) is a one-dimensional Hann weight, zero at the endpoints. \(Q_{t,i}\) is the extracted centered grayscale crop and \(\overline Q_{t,i}\) its scalar pixel mean. \(P_{t,i}\) is the mean-subtracted crop multiplied by the horizontal and vertical Hann weights. This P is an image patch, not an output probability.',
r'\(F_{t,i}\) is the complex Fourier transform of the windowed patch after zero-padding to 32 × 32. FFT and IFFT are the forward and inverse transforms. A bar over the complex F means complex conjugation, unlike the scalar mean bar over Q. \(R^\ell_{t,i}\) is a grid of correlation scores between the earlier frame \(t_\ell\) and current frame t. \(E_{t,i}\) is total squared energy of the windowed crop; it differs from the 10 × 10 raw grayscale energy e above.',
r'\(\mathbf d=(d_x,d_y)\) is a candidate displacement in pixels. \(C^\ell_{t,i,\mathbf d}\) divides correlation R at that displacement by the geometric mean of the two crop energies. The maximum imposes a numerical floor of \(10^{-8}\). \(r^\ell_{t,i}\) is a separate reliability factor between zero and one, using the constant 0.01. For negligible energy, r suppresses the contribution even if a normalized score would be misleading.',
r'\(f_\theta\) is the small learned convolutional refinement, with parameters collectively denoted \(\theta\). \(\widetilde C\) is the refined score. \(\eta_\ell\) is a learned log-temperature; exponentiation makes temperature positive and clip restricts it to the stated interval. \(p^\ell_{t,i,k}\) is the normalized score for candidate k, and j runs over all 81 candidates in the denominator. Scores sum to one separately at each time, site, and lag. Here p is a displacement weight, not a pixel index.',
r'\(\mathbf d_k\) is the fixed two-dimensional displacement of candidate k. The hat marks the weighted displacement estimate \(\widehat{\mathbf d}\). Dividing it by nominal frame lag \(\ell\) gives velocity \(\widehat{\mathbf v}\) in pixels per observation. This is an expectation over alternatives, not the displacement with the largest score.',
r'\(\bar{\mathbf v}_{t-1,i}\) averages the three lag-specific velocities available at the preceding frame. \(\mathbf x\) is a destination pixel coordinate. Upsample interpolates the coarse field to that pixel. \(\widehat I_t^{\rm gray}\) is the predicted grayscale image; it samples the actual preceding image \(I_{t-1}^{\rm gray}\) at the displayed source coordinate. If the prior estimate is two pixels rightward, a destination pixel reads from two pixels to its left.',
r'\(\epsilon_{t,i}\) is the block’s mean squared prediction error divided by its average raw grayscale energy across adjacent frames. \(\omega_{t,i}\) is a separate energy-based weight for the auxiliary loss. The numerator compares predicted and observed grayscale at the same destination pixel. Both occurrences of \(10^{-4}\) are fixed stabilizing constants. Error epsilon here is not the small numerical epsilon used in vector normalization later.',
r'\(Z^\ell_{t-1,i,k}\) is the preceding local population trace; \(p^\ell_{t,i,k}\) is the current population. \(\delta\) sums their absolute differences over candidates. \(\rho=\sigma(\zeta)\) is one learned rate shared by the trace, where \(\zeta\) is an unconstrained scalar. Multiplication by reliability r slows replacement when the crop has little energy. The new trace moves partway toward p; its initial 81 entries are each 1/81.',
r'W labels a reference window R or a recent window O; it is not a learned weight matrix here. \(W_t\) is the set of frame indices belonging to that window, s indexes its available frames, and \(L_W\) is its nominal length. \(\bar p_W\) is the reliability-weighted mean population. \(q_W\) is total available reliability divided by nominal length, so an incomplete window has reduced confidence. If no reference frames exist, both its population and confidence are zero.',
r'\(q=\sqrt{q_Rq_O}\) requires confidence in both windows. \(\Delta p\) is their entrywise absolute difference, distinct from the feature width D=64. The brackets concatenate three 81-entry vectors and two scalars. The last scalar uses cosine similarity: a dot product divided by vector lengths. \(b^\ell_{t,i}\) therefore contains 245 entries, and all three lags give 735. In a seven-frame VDA trial the reference window never becomes available: q and this entire comparison vector stay zero.',
r'\(f_{t,i}\) collects the named local features into one 292-entry vector; braces mean include all three lags, not average them. \(V_{t,i}\) is the resulting 64-entry visual token. \(W_f\) maps 292 inputs to 64 outputs, \(b_f\) is its learned bias, and \(e_i^{\rm pos}\) is a learned 64-entry position code. This position code is distinct from the windowed image patch P and the grayscale energy e.',
])

p=S/'memory.html';s=p.read_text(encoding='utf-8')
s=s.replace('The heads add 1,950 parameters in total.','The 16 heads add 2,340 parameters in total, compared with 1,950 in the 13-task parent.')
s=s.replace(r'\sum_{b=1}^B-\log',r'\sum_{b=1}^B u_b[-\log').replace(r'P_\theta(y_b\mid X_b,a)+0.05',r'P_\theta(y_b\mid X_b,a)]+0.05')
s=s.replace('one update to each of 13 tasks','one update to each of 16 tasks in the VDA continuation (13 in the original suite)')
s=s.replace(r'g=\nabla_\theta\mathcal L,\qquad g^{\rm clip}=g\min\left(1,\frac{100}{\|g\|_2}\right)',r'\mathbf g=\nabla_\theta\mathcal L,\qquad \mathbf g^{\rm clip}=\mathbf g\min\left(1,\frac{100}{\max(\|\mathbf g\|_2,10^{-6})}\right)')
s=s.replace(r'g_n^{\rm clip}',r'\mathbf g_n^{\rm clip}')
s=s.replace('Concatenate current values',r'Here \(V_t^{\rm value}\) means the 100 vectors \(v_{t,i}\) reshaped into a 64 × 10 × 10 field; it is not the earlier token \(V_{t,i}\). Concatenate current values')
p.write_text(s,encoding='utf-8')
notes('memory',[
r'\(h_{t-1,i}\) is the 64-entry vector stored at location i in the previous spatial field H. LN with different subscripts denotes different learned normalization layers. \(W_K\) produces a key k describing that site; \(W_Q\) produces the single query q from previous global memory c and the learned constant \(c_*\). Both are 64-entry vectors. The query is shared across locations, while keys differ by location.',
r'\(\kappa\) is a learned scalar controlling similarity scale s; sigmoid keeps s between 1 and 16. \(\mathcal N_\varepsilon\) divides a vector by its length with a small denominator floor. The dot product then measures directional alignment. \(\ell_{t,i}\) is the unnormalized attention score, called a logit; \(\alpha_{t,i}\) is its softmax weight. The denominator sums all spatial sites, so the 100 weights total one. This italic logit symbol is distinct from the lag label used in the correspondence chapter.',
r'\(W_V,W_H,W_1,W_2\) are learned channel-mixing matrices; b labels their learned biases. \(u\) combines current visual and previous memory information. \(v\) adds a nonlinear residual to u. The inner transformation expands 64 channels to 256; the outer one returns to 64. There is no spatial pooling in this equation.',
r'\(z_t\) is the selected 64-entry value summary. \(b_t^{\rm selected}\) is the selected 735-entry local comparison. Both use exactly the same attention weights. \(m_t\) stores a running comparison trace: retain 80% of its previous value and add 20% of the current selected comparison. “Selected” labels the vector; it is not a power or an additional learned module.',
r'\(g_{t,i}\) is one scalar write multiplier per spatial site, shared across its channels. It converts attention mass \(\alpha_{t,i}\) to a bounded write factor relative to uniform mass 1/N. For N=100 and alpha=0.01, g=0.01/0.02=0.5. It is distinct from the global training-gradient vector written in bold later.',
r'a is the vector being normalized, j indexes its 64 channels, and D=64. \(\mu\) is its channel mean and \(\nu\) its channel variance using divisor D. \(\gamma_j\) and \(\beta_j\) are learned scale and offset for channel j, not attention gains or optimizer moment coefficients. Subtract the mean, divide by the stabilized standard deviation, then apply those learned affine parameters.',
r'\(K_g\) and \(b_g\) are a learned spatial convolution and bias. The two halves of its output are \(a^w\), the write preactivation, and \(a^r\), the reset preactivation. Separate LayerNorms and sigmoids convert them to channelwise fractions w and r. Superscripts w and r name the two gates; they are not exponents. The reset r here is distinct from correspondence reliability in the previous chapter.',
r'\(K_h,b_h\) create a candidate memory field from current values and reset-filtered old memory. The circle-dot multiplies corresponding channels; tanh bounds the candidate \(\widetilde H\) to −1 through 1. \(\bar w_{t,i,j}\) is the effective write fraction for channel j at location i: spatial multiplier g times learned write fraction w.',
r'Each coordinate retains fraction \(1-\bar w\) of the old state and receives fraction \(\bar w\) of the candidate. Example: old state 0.8, candidate −0.2, learned write fraction 0.6, and spatial multiplier 0.5 give effective write 0.3 and new state 0.8 + 0.3(−0.2 − 0.8)=0.5. Normalization shapes the proposed update; it does not rescale the stored H after this interpolation.',
r'The superscript c labels global CLS gates. \(W_{cg},b_{cg}\) transform the concatenated current summary z and previous global memory c into 128 entries. Subscripts w and r outside the brackets take the first and second 64-entry halves. Independent normalization layers produce write and reset gates as in spatial memory, but there is no spatial convolution.',
r'\(W_{ch},b_{ch}\) compute the global candidate \(\widetilde c\). Reset fractions control how much previous c participates in this proposal; write fractions interpolate between old c and the proposal. This is the same retention logic as the spatial equation, applied to a single 64-entry summary. The resulting c is used both for the final response and the next frame’s query.',
r'\(h^{\rm out}\) is the shared 64-entry decision representation; it is not the spatial memory h. \(W_o,b_o\) map the concatenated 799-entry final state to it. Task index a chooses \(W_a,b_a\), producing answer logits \(L^{(a)}\). Softmax normalizes over answer classes k, not image locations. y denotes the answer class and X the entire movie. This probability need not be calibrated confidence.',
r'B is the number of trials, b indexes trials, T their frame count, and N=100 the patch count. \(y_b\) is the correct terminal answer. The first term is negative log probability of that answer, weighted by \(u_b\): 1 for the original tasks, cue value/3 for VDA. The second term averages reliability-weighted pixel error over trials, noninitial frames, and sites. The learned parameters are collectively \(\theta\); 0.05 fixes the relative pixel-loss coefficient. The weight u here is a trial scalar, distinct from a value vector u earlier.',
r'\(\mathbf g\) contains derivatives of the loss with respect to all active learned parameters, joined for one global Euclidean norm. Clipping scales the whole vector only if its norm exceeds 100; a zero gradient remains zero. The displayed denominator floor prevents division by zero. The library uses a small additive numerical epsilon in its denominator; this is the same clipping rule up to that numerical convention. This operation occurs in optimization, not during the forward memory update.',
r'n counts optimizer updates for the parameter in question. M and U are running first and squared-gradient moments, distinct from model memory m. \(\beta_1=0.9\), \(\beta_2=0.999\), and \(\eta=0.0003\). Powers \(\beta_1^n,\beta_2^n\) correct zero-initialized moments. Squaring, square roots, and division act coordinatewise. These optimizer variables persist across training updates but are not trial memory and are not used to answer an evaluation movie.',
])

p=S/'flow.html';s=p.read_text(encoding='utf-8')
s=s.replace(r'\int\!\left(I_xu+I_yv+I_t\right)^2+\lambda\left(\|\nabla u\|^2+\|\nabla v\|^2\right)\,dx\,dy',r'\int\!\left[\left(I_xu+I_yv+I_t\right)^2+\lambda\left(\|\nabla u\|^2+\|\nabla v\|^2\right)\right]\,dx\,dy')
s=s.replace('The 2 × 2 matrix', 'The inverse formula applies only when G is invertible; otherwise a unique local velocity cannot be recovered by this expression. The 2 × 2 matrix')
s=s.replace("Farnebäck's method instead approximates", "In the following local polynomial, x is a two-dimensional pixel coordinate, A is a symmetric 2 × 2 curvature matrix, b is a two-entry linear coefficient vector, and c is a constant intensity offset. Subscripts 1 and 2 distinguish earlier and later local approximations. Farnebäck's method instead approximates")
s=s.replace('Reversing motion reverses',r'Here A(t) and B(t) are signals at two spatially separated receptors at time t, and \(\delta\) is a temporal delay; R is the difference of the two ordered products. Reversing motion reverses')
p.write_text(s,encoding='utf-8')
notes('flow',[
r'I is scalar image intensity as a function of horizontal position x, vertical position y, and time t. u and v are horizontal and vertical velocities; multiplying by the small interval \(\Delta t\) converts them to displacements. The equality assumes that a moving pattern retains its brightness over that interval. It is an assumption about image formation, not an identity that all movies satisfy.',
r'\(I_x,I_y,I_t\) denote derivatives of intensity with respect to x, y, and time—not three frames or RGB channels. \(\nabla I=(I_x,I_y)\) is the spatial gradient and \(\mathbf v=(u,v)\) the velocity vector. A dot product sums the horizontal and vertical contributions. One scalar constraint cannot generally determine both unknown velocity components.',
r'\(E(\mathbf v)\) is the fitting error for one assumed local velocity, \(\Omega\) the neighborhood, p a pixel, and \(w_p\) a nonnegative pixel weight. The transposed gradient dotted with velocity predicts an intensity change; adding the observed temporal derivative gives its residual. Square each residual, weight it, and sum. This E is an objective, not a neural energy measurement.',
r'G is the 2 × 2 sum of weighted gradient outer products, and \(\mathbf b\) is the weighted sum of gradients multiplied by temporal derivatives. The superscript −1 means matrix inverse. Solving this linear system estimates the two velocity components. This G belongs only to the Lucas–Kanade tutorial; it never denotes the green channel or grayscale image.',
r'\(E[u,v]\) scores entire horizontal and vertical velocity fields. The integral sums over image position. \(\nabla u\) and \(\nabla v\) are spatial derivatives of those fields; their squared lengths penalize rapid spatial changes. The positive constant \(\lambda\) controls how much smoothness is favored relative to brightness agreement. Both terms are inside the spatial integral.',
r'\(\widetilde A\) and \(\widetilde B\) are the two mean-centered, windowed image patches; the tilde labels that preprocessing. \(\mathbf x\) indexes a patch pixel and \(\mathbf d\) a candidate shift. The numerator adds products of aligned pixels; the denominator normalizes by the two patch energies, with a \(10^{-8}\) floor. This scores how well a proposed shift matches the patches.',
r'I is an image sequence and * here is filtering over space and time. \(f_1,f_2\) are a phase-offset filter pair tuned to one motion direction. Squaring and summing their responses gives \(E_+\); another pair tuned oppositely gives \(E_-\). M subtracts those energies to express directional opposition. The + and − label directions, not positive and negative pixel intensities.',
])

p=S/'introduction.html';s=p.read_text(encoding='utf-8')
s=re.sub(r'<details class="hypothesis" open>.*?</details>', '''<div class="callout"><strong>The evidence now available</strong><p>The completed 13-task suite showed broad performance with remaining difficult conditions. A continuation added VDA4, VDA9, and VDA16 while preserving the shared architecture. In its frozen VDA4 experiment, inhibiting a perfectly cued bottom-right region increased detection of unexpected top-left changes from 48.2% to 68.0%, while reducing bottom-right detection from 87.0% to 6.5%. This is evidence for a location-dependent trade-off in one trained model. Earlier motion and cued-orientation tests did not establish their primary balanced-accuracy benefits. The combined evidence supports a shared, causally manipulable computational interface; it does not establish a unique biological circuit, universal benefits, or replication across independent training seeds. <a href="#results">Read the results and their limits.</a></p></div>''',s,flags=re.S)
p.write_text(s,encoding='utf-8')
p=S/'tasks.html';s=p.read_text(encoding='utf-8').replace('Thirteen tasks span 35 primary conditions.','The original thirteen tasks span 35 primary conditions; the three VDA additions bring the completed continuation to 16 tasks and 44 conditions. This atlas covers the original thirteen; the <a href="#vda-tasks">VDA chapter</a> explains the added protocols and links their own trial atlas.')
p.write_text(s,encoding='utf-8')

p=S/'experiments.html';s=p.read_text(encoding='utf-8')
start=s.index('<h3>What “stimulate')
s='<section id="experiments" class="chapter"><div class="eyebrow">07 · Interventions and further tests</div><h2>Make the hypothesis<br>answer to experiments.</h2><p class="lead">The frozen results are reported in the next chapter. This chapter defines the intervention, explains the measurements, and separates completed analyses from tests that still need to be done.</p>'+s[start:]
s=re.sub(r'<section id="results".*?</section>','',s,flags=re.S)
s=s.replace('The Results section remains intentionally empty; all interactive architecture figures are teaching demonstrations.','Measured results are linked to their saved analysis records; interactive architecture figures remain teaching demonstrations.')
s=s.replace('<h3>Proposed experiment 1:', '<h3>Cross-domain test, partly completed:')
s=s.replace('First establish reliable performance separately','The original suite and VDA analyses provide task performance and matched interventions, but not an independent-seed, matched-difficulty cross-domain replication. For that stronger test, first establish reliable performance separately')
s=s.replace('<h3>Proposed experiment 4:', '<h3>Psychometrics, completed analyses and further extensions:')
s=s.replace('Vary the relevant evidence magnitude','The two frozen galleries contain empirical psychometric points. The equation below is an optional descriptive fit, not a claim that those plots were generated from this fitted function. Vary the relevant evidence magnitude')
s=s.replace('Then</p>',r'\(\ell_{t,i}\) is the original logit at time t and site i; \(\ell\prime\) below means its intervened value. \(\beta\) is the signed bias magnitude. The temporal mask \(a_t\) is 1 during intervention frames and 0 otherwise; the spatial mask \(M_i\) is 1 inside the selected region and 0 outside. A prime labels the manipulated quantity. Then</p>',1)
s=s.replace(r'\(\ell\prime\)',r'\(\ell\!\;{}^{\prime}\)')
s=s.replace('Here \\(\\gamma\\)',r'Here x is evidence magnitude (such as absolute rotation in degrees), P(report | x) is the probability of a positive response, a is a positive scale parameter in the same units as x, and b is a positive shape parameter. These a and b belong only to this curve, not the intervention mask or model bias vectors. Here \(\gamma\)')
s=s.replace('finite-sample corrections are needed at 0 or 1.',r'\(\Phi^{-1}\) is the inverse cumulative distribution of a standard normal variable. H is the fraction of event trials reported as change and F the fraction of no-change catches reported as change. d-prime measures their separation on that normal-score scale; c summarizes the response criterion under that descriptive model. Finite-sample corrections are needed at 0 or 1.')
p.write_text(s,encoding='utf-8')
print('Migrated authored sections and added local explanations for 35 implementation/tutorial equations.')
